package ratelimit

import (
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	mu  sync.Mutex
	now time.Time
}

func newFakeClock() *fakeClock {
	return &fakeClock{now: time.Unix(0, 0)}
}

func (f *fakeClock) Now() time.Time {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.now
}

func (f *fakeClock) Advance(d time.Duration) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.now = f.now.Add(d)
}

func TestNewValidation(t *testing.T) {
	cases := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"nil clock", 5, 1, nil, true},
		{"zero capacity", 0, 1, newFakeClock(), true},
		{"negative capacity", -1, 1, newFakeClock(), true},
		{"zero rate", 5, 0, newFakeClock(), true},
		{"negative rate", 5, -1, newFakeClock(), true},
		{"valid", 5, 1, newFakeClock(), false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			b, err := New(tc.capacity, tc.rate, tc.clock)
			if (err != nil) != tc.wantErr {
				t.Fatalf("err = %v, wantErr = %v", err, tc.wantErr)
			}
			if !tc.wantErr && b == nil {
				t.Fatal("expected bucket")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	cases := []struct {
		name    string
		advance time.Duration
		n       int
		want    bool
	}{
		{"initial allow", 0, 1, true},
		{"zero n", 0, 0, true},
		{"negative n", 0, -1, false},
		{"exceeds capacity", 0, 6, false},
		{"refill after advance", 2 * time.Second, 4, true},
		{"partial refill", 1500 * time.Millisecond, 2, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			fc := newFakeClock()
			b, err := New(5, 2, fc)
			if err != nil {
				t.Fatal(err)
			}
			if tc.advance > 0 {
				fc.Advance(tc.advance)
			}
			if got := b.AllowN(tc.n); got != tc.want {
				t.Fatalf("AllowN(%d) = %v, want %v", tc.n, got, tc.want)
			}
		})
	}
}

func TestAllowNConsumesTokens(t *testing.T) {
	fc := newFakeClock()
	b, err := New(5, 1, fc)
	if err != nil {
		t.Fatal(err)
	}
	if !b.AllowN(3) {
		t.Fatal("first AllowN(3) failed")
	}
	if b.AllowN(3) {
		t.Fatal("second AllowN(3) should fail")
	}
	if !b.AllowN(2) {
		t.Fatal("AllowN(2) should succeed")
	}
}

func TestAllowNConcurrent(t *testing.T) {
	fc := newFakeClock()
	b, err := New(10, 1, fc)
	if err != nil {
		t.Fatal(err)
	}
	var wg sync.WaitGroup
	var mu sync.Mutex
	allowed := 0
	for i := 0; i < 20; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if b.AllowN(1) {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if allowed != 10 {
		t.Fatalf("allowed = %d, want 10", allowed)
	}
}
